-- Coverage per state/UT (editorial notes on published destinations).
select d.region,
       count(distinct d.id) as destinations,
       count(s.id) filter (where s.source = 'editorial') as editorial_notes,
       count(s.id) filter (where s.source = 'community') as community_stories
from public.destinations d
left join public.stories s on s.destination_id = d.id and s.status = 'published'
where d.slug in ('manali', 'spiti-valley', 'mcleod-ganj', 'shimla', 'bir-billing', 'amritsar', 'anandpur-sahib', 'patiala', 'morni-hills', 'sultanpur-national-park', 'kurukshetra', 'pinjore', 'valley-of-flowers', 'rishikesh', 'pithoragarh', 'chopta', 'nainital', 'agra', 'varanasi', 'lucknow', 'prayagraj', 'jaipur', 'bundi', 'jaisalmer', 'udaipur', 'pushkar', 'delhi', 'chandigarh', 'srinagar', 'gulmarg', 'pahalgam', 'leh', 'nalanda', 'bodh-gaya', 'rajgir', 'vaishali', 'deoghar', 'netarhat', 'ranchi', 'betla-national-park', 'koraput', 'puri', 'konark', 'chilika-lake', 'bhitarkanika', 'darjeeling', 'kolkata', 'sundarbans', 'shantiniketan', 'gangtok', 'pelling', 'lachung', 'kaziranga', 'majuli', 'guwahati', 'sivasagar', 'tawang', 'ziro', 'dirang', 'sohra', 'dawki', 'mawlynnong', 'shillong', 'loktak-lake', 'imphal', 'ukhrul', 'aizawl', 'reiek', 'champhai', 'kohima', 'dzukou-valley', 'khonoma', 'unakoti', 'agartala', 'neermahal', 'udaipur-tripura', 'sri-vijaya-puram', 'swaraj-dweep', 'gandikota', 'araku-valley', 'tirupati', 'lepakshi', 'warangal', 'hyderabad', 'ananthagiri-hills', 'hampi', 'mysuru', 'madikeri', 'gokarna', 'badami', 'munnar', 'varkala', 'kozhikode', 'alappuzha', 'fort-kochi', 'thekkady', 'ooty', 'madurai', 'mahabalipuram', 'rameswaram', 'kodaikanal', 'karaikudi', 'anjuna', 'palolem', 'old-goa', 'dudhsagar', 'panaji', 'puducherry', 'agatti', 'rann-of-kutch', 'sasan-gir', 'ahmedabad', 'ekta-nagar', 'dholavira', 'ajanta-caves', 'ellora-caves', 'mumbai', 'malvan', 'ganpatipule', 'lonavala', 'khajuraho', 'orchha', 'pachmarhi', 'kanha', 'sanchi', 'mandu', 'chitrakote', 'jagdalpur', 'mainpat', 'sirpur', 'diu', 'daman')
group by d.region
